EXECUTE(' 		select 		data,  		hora, 		loja, 		caixa, 		nfce_chave, 		cupom, 		coo,  		ecf,  		status, 		item, 		case when cdprod = "" then 0 else cdprod end as cdprod, 		quant, 		preco, 		valortot, 		desccupom, 		abatpgto, 		descitem, 		acrescupom, 		acresitem, 		tipopagto, 		cast(case when tributacao = "" then 0.00 else substring(tributacao,2,5) end as decimal(5,2) ) as tributacao, 		cgc, 		banco, 		case when substring(banco,2,2) <> "" and status = 01 			then 				case when substring(banco,2,2) = "60" 					then "5.405" 					else "5.102" 				end 			else "" 		end agencia, 		cancelado, 		cstpis, 		aliqpis, 		cstcofins, 		aliqcofins, 		precocusto		 		 		FROM movcaixa 		where 		data between "20180801" and "20180831"  and  		status IN(01,02) and  		cancelado <> "S" 		 		order by  		data, 		nfce_chave, 		status, 		item 		 		') at MYSQLGZ